use crate::geometry::Point;

pub fn earcut(polygon: &[Vec<Point>]) -> Vec<u32> {
    let Some(ring) = polygon.first() else {
        return Vec::new();
    };

    triangulate_ring(ring)
}

fn triangulate_ring(ring: &[Point]) -> Vec<u32> {
    let vertex_count = ring.len();
    if vertex_count < 3 {
        return Vec::new();
    }

    let mut prev = vec![0_usize; vertex_count];
    let mut next = vec![0_usize; vertex_count];

    for index in 0..vertex_count {
        prev[index] = if index == 0 { vertex_count - 1 } else { index - 1 };
        next[index] = if index + 1 == vertex_count { 0 } else { index + 1 };
    }

    let mut indices = Vec::with_capacity((vertex_count - 2) * 3);
    let mut remaining = vertex_count;
    let mut ear = vertex_count - 1;

    // The generated ring is convex, so every vertex is an ear. Advancing by two
    // after each cut reproduces the reference executable's index order.
    while remaining > 3 {
        let previous = prev[ear];
        let following = next[ear];
        push_triangle(&mut indices, previous, ear, following);

        next[previous] = following;
        prev[following] = previous;
        remaining -= 1;
        ear = next[following];
    }

    let previous = prev[ear];
    let following = next[ear];
    push_triangle(&mut indices, previous, ear, following);

    indices
}

fn push_triangle(indices: &mut Vec<u32>, a: usize, b: usize, c: usize) {
    indices.push(a as u32);
    indices.push(b as u32);
    indices.push(c as u32);
}

