pub type Point = [f64; 2];

pub fn build_polygon(n: i32) -> Vec<Vec<Point>> {
    let mut polygon = Vec::with_capacity(1);
    let vertex_count = i64::from(n) * 3;
    let mut ring = Vec::new();

    if vertex_count > 0 {
        ring.reserve(vertex_count as usize);
        let denominator = vertex_count as f64;

        for i in 0..vertex_count {
            let angle = 2.0 * std::f64::consts::PI * i as f64 / denominator;
            ring.push([angle.cos(), angle.sin()]);
        }
    }

    polygon.push(ring);
    polygon
}

